<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import PlainTextEditor from '../../../desktop/src/renderer/ui/PlainTextEditor.vue'
import ChapterTreeList from '../../../desktop/src/renderer/features/manuscript/components/ChapterTreeList.vue'
import type { Chapter, ChapterRevision, WritingAgentSkillId, WritingAgentSelection } from '../../../desktop/src/contracts/index'
import { writing, points, type BookApi, type Job, type JobSummary, type Model } from '../api/writing'
import { messageOf, type Session } from '../api/http'
import Annotations from './Annotations.vue'
import ImportBook from './ImportBook.vue'
import { DraftStore } from './drafts'
const importOpen = ref(false)
const props = defineProps<{ api: BookApi; session: Session }>()
const emit = defineEmits<{ 'refresh-wallet': [] }>()
const chapters = ref<Chapter[]>([]), chapter = ref<Chapter | null>(null), content = ref(''), title = ref(''), error = ref(''), notice = ref(''), busy = ref(false), loading = ref(true), composing = ref(false), editor = ref<InstanceType<typeof PlainTextEditor> | null>(null)
const models = ref<Model[]>([]), model = ref(''), instruction = ref(''), skill = ref<WritingAgentSkillId>('continue'), selection = ref<WritingAgentSelection>(), jobs = ref<JobSummary[]>([]), job = ref<Job | null>(null), jobError = ref(''), jobBusy = ref(false), adoptBusy = ref(false), allowFailedReview = ref(false), accepted = ref<string[]>([])
const recovery = ref<{ title: string; content: string; baseline: string } | null>(null), versions = ref<ChapterRevision[] | null>(null), chosenVersion = ref<ChapterRevision | null>(null)
const store = new DraftStore(sessionStorage, props.session.user.id, props.api.id)
let selectedJobId = '', epoch = 0, alive = true, timer: ReturnType<typeof setTimeout> | undefined, createOperation = crypto.randomUUID(), jobOperation = crypto.randomUUID(), jobPayload = ''
const dirty = computed(() => Boolean(chapter.value && (content.value !== chapter.value.content || title.value !== chapter.value.title)))
const running = computed(() => job.value && ['queued', 'running'].includes(job.value.status))
const selectedModel = computed(() => models.value.find(m => m.id === model.value))
const priceLabel = computed(() => { const price = selectedModel.value?.price.policy; return !price || price.mode === 'unconfigured' ? '站长尚未配置计费' : price.mode === 'request' ? `${points(price.points)} 积分 / 任务（内部审校包含在内）` : price.mode === 'provider-tokens' ? `按供应商实际用量折算 · 1 美元余额 = ${price.usdToCny} 元` : `输入 ${points(price.inputPerMillion)} / 输出 ${points(price.outputPerMillion)} 积分每百万 tokens` })
const candidate = computed(() => job.value?.task?.turn?.candidate)
const report = computed(() => job.value?.task?.turn?.proposal?.report)
watch([content, title], () => { if (!chapter.value || !dirty.value) return; try { store.write(`chapter:${chapter.value.id}`, chapter.value.revision!, { title: title.value, content: content.value }) } catch { error.value = '浏览器恢复空间不足，请立即保存或下载当前草稿。' } }, { flush: 'sync' })
async function choose(item: Chapter, fromAdoption = false) { if (busy.value || composing.value || (adoptBusy.value && !fromAdoption)) return; const token = ++epoch; loading.value = true; error.value = ''; recovery.value = null; versions.value = null
  try { const actual = await props.api.chapter(item.id); if (!alive || token !== epoch) return
    chapter.value = null; title.value = actual.title; content.value = actual.content; chapter.value = actual; selection.value = undefined
    const copy = store.read<{ title: string; content: string }>(`chapter:${actual.id}`)
    if (copy && typeof copy.data?.content === 'string' && typeof copy.data?.title === 'string' && (copy.data.content !== actual.content || copy.data.title !== actual.title)) recovery.value = { ...copy.data, baseline: copy.baseline }
  } catch (e) { if (token === epoch) error.value = messageOf(e) } finally { if (token === epoch) loading.value = false } }
async function refresh() { const list = await props.api.chapters(); if (!alive) return; chapters.value = list; if (!chapter.value && list[0]) await choose(list[0]); loading.value = false }
async function create() { if (busy.value || composing.value) return; busy.value = true; error.value = ''; try { const created = await props.api.createChapter(createOperation); createOperation = crypto.randomUUID(); chapters.value = await props.api.chapters(); busy.value = false; await choose(created) } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function save(): Promise<boolean> { if (!chapter.value || busy.value || composing.value) return false; if (!dirty.value) return true; const captured = chapter.value, token = epoch, sent = { title: title.value, content: content.value }; busy.value = true; error.value = ''
  try { const updated = await props.api.saveChapter(captured.id, { ...sent, expectedRevision: captured.revision! }); if (!alive || epoch !== token) return false
    chapter.value = updated; chapters.value = chapters.value.map(c => c.id === updated.id ? updated : c); if (!dirty.value) store.remove(`chapter:${captured.id}`); notice.value = dirty.value ? '上一版已保存；新修改仍在编辑器中。' : '正文已保存。'; return !dirty.value
  } catch (e) { if (epoch === token) error.value = messageOf(e); return false } finally { busy.value = false } }
function restoreCopy() { if (!recovery.value || !chapter.value) return; title.value = recovery.value.title; content.value = recovery.value.content; recovery.value = null; notice.value = '已恢复到编辑器，请与服务端版本核对后保存。' }
async function history() { if (!chapter.value) return; error.value = ''; const token = epoch; try { const result = await props.api.history(chapter.value.id); if (token === epoch && alive) versions.value = result } catch (e) { error.value = messageOf(e) } }
async function restoreVersion() { if (!chapter.value || !chosenVersion.value || busy.value || composing.value) return; busy.value = true; try { const restored = await props.api.restore(chapter.value.id, chosenVersion.value.id, chapter.value.revision!); busy.value = false; chosenVersion.value = null; await choose(restored); notice.value = '已恢复所选历史版本；原有版本仍保留。' } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
function downloadDraft() { const url = URL.createObjectURL(new Blob([`# ${title.value}\n\n${content.value}`], { type: 'text/markdown;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = '岚笺-当前草稿.md'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
async function poll(id: string) { clearTimeout(timer); try { const value = await props.api.job(id); if (!alive || selectedJobId !== id) return; job.value = value; jobError.value = ''; if (['queued', 'running'].includes(value.status)) timer = setTimeout(() => { void poll(id) }, 1800); else { jobs.value = await props.api.jobs(); emit('refresh-wallet') } } catch (e) { if (alive && selectedJobId === id) jobError.value = messageOf(e) } }
async function openJob(id: string) { selectedJobId = id; clearTimeout(timer); job.value = null; accepted.value = []; allowFailedReview.value = false; await poll(id); if (selectedJobId !== id) return; accepted.value = candidate.value?.diff?.filter(b => b.kind === 'change').map(b => b.id) ?? [] }
async function generate() { if (!chapter.value || jobBusy.value || composing.value || running.value) return; if (dirty.value && !await save()) return; jobBusy.value = true; jobError.value = ''; const request = { chapterId: chapter.value.id, currentDraft: content.value, message: instruction.value || (skill.value === 'continue' ? '按当前已确认章纲继续写作' : '分析当前章节'), preferredSkill: skill.value, ...(skill.value === 'rewrite' && selection.value?.text ? { selection: selection.value } : {}) }; const payload = JSON.stringify([model.value, request]); if (payload !== jobPayload) { jobOperation = crypto.randomUUID(); jobPayload = payload }
  try { const id = await props.api.generate(jobOperation, model.value, request); jobOperation = crypto.randomUUID(); await openJob(id); emit('refresh-wallet') } catch (e) { jobError.value = messageOf(e) } finally { jobBusy.value = false } }
async function stop() { if (!job.value || jobBusy.value) return; jobBusy.value = true; try { await props.api.cancel(job.value.id); await poll(job.value.id) } catch (e) { jobError.value = messageOf(e) } finally { jobBusy.value = false } }
async function adopt() { if (!chapter.value || !job.value?.task || adoptBusy.value || composing.value || dirty.value) return; adoptBusy.value = true; error.value = ''; try { const result = await props.api.adopt({ taskId: job.value.task.id, title: title.value, expectedRevision: chapter.value.revision!, formatting: { firstLineIndent: false, paragraphSpacing: true }, ...(candidate.value?.diff ? { acceptedChangeIds: accepted.value } : {}), allowFailedReview: allowFailedReview.value }); await choose(result.chapter, true); await poll(job.value.id); notice.value = '已采用到正文。' } catch (e) { error.value = messageOf(e) } finally { adoptBusy.value = false } }
function beforeUnload(event: BeforeUnloadEvent) { if (dirty.value) { event.preventDefault(); event.returnValue = '' } }
onMounted(async () => { window.addEventListener('beforeunload', beforeUnload); try { await refresh(); models.value = await writing.models(); model.value = models.value[0]?.id ?? ''; jobs.value = await props.api.jobs(); const latest = jobs.value[0]; if (latest) await openJob(latest.id) } catch (e) { error.value = messageOf(e); loading.value = false } })
onBeforeUnmount(() => { alive = false; epoch++; clearTimeout(timer); window.removeEventListener('beforeunload', beforeUnload) })
</script>
<template><div class="writing-desk"><aside class="chapter-index"><header><h2>章节目录</h2><button :disabled="busy || composing" @click="create">＋ 新章</button></header><ChapterTreeList :chapters="chapters" :selected-id="chapter?.id ?? null" :selected-title="title" @select="choose" /><p v-if="!chapters.length && !loading" class="muted">新建第一章，开始落笔。</p><footer><button @click="importOpen = true">导入稿件</button><a :href="api.exportUrl('markdown')" download>导出 Markdown</a><a :href="api.exportUrl('txt')" download>导出 TXT</a></footer></aside><section class="manuscript-column"><div class="editor-toolbar"><span class="eyebrow">05 / MANUSCRIPT</span><div><button :disabled="!chapter || composing" @click="editor?.undo()">撤销</button><button :disabled="!chapter || composing" @click="editor?.redo()">重做</button><button :disabled="!chapter" @click="history">历史</button><button :disabled="!chapter" @click="downloadDraft">下载草稿</button></div></div><p v-if="error" class="error" role="alert">{{ error }} <button v-if="chapter" @click="choose(chapter)">重读服务端版本</button></p><p v-if="notice" class="success" role="status">{{ notice }}</p><aside v-if="recovery" class="recovery-note"><b>发现未保存的草稿</b><p>{{ recovery.baseline === chapter?.revision ? '可恢复上一次在此标签页中的输入。' : '服务端正文已有变化。恢复副本后请核对差异，再保存。' }}</p><button @click="restoreCopy">恢复到编辑器</button><button @click="recovery = null">暂不恢复</button></aside><div v-if="chapter" class="manuscript-paper"><label class="manuscript-title"><span>第 {{ chapter.position }} 章</span><input v-model="title" aria-label="章节标题" :disabled="adoptBusy"></label><PlainTextEditor ref="editor" v-model="content" :document-key="`${api.id}:${chapter.id}`" ariaLabel="正文内容" :read-only="adoptBusy || loading" placeholder="在这里写下故事的第一句话…" comfortable-caret @save="save" @selection="selection = $event" @composition-start="composing = true" @composition-end="composing = false" /></div><div v-else class="empty-state"><h2>{{ loading ? '正在打开书稿…' : '落笔成章' }}</h2><p>点击「新章」开始写作。</p></div><footer class="editor-status"><span>{{ content.length.toLocaleString() }} 字符 · {{ dirty ? '尚未保存' : chapter ? '已保存' : '等待打开章节' }}</span><button class="primary" :disabled="!chapter || busy || composing || adoptBusy" @click="save">{{ busy ? '保存中…' : '保存正文' }}</button></footer></section><aside class="writing-assistant"><header><h2>AI 助笔</h2><p>帮你展开故事，决定权留给你。</p></header><label>站长提供的模型<select v-model="model"><option v-if="!models.length" value="">暂无可用模型</option><option v-for="m in models" :key="m.id" :value="m.id">{{ m.name }}</option></select></label><p class="fee-description">{{ priceLabel }}</p><p class="muted">可用 {{ points(session.wallet.available) }} 积分<span v-if="session.wallet.reserved"> · 预留 {{ points(session.wallet.reserved) }}</span></p><label>写作任务<select v-model="skill"><option value="continue">按章纲续写</option><option value="query">讨论 / 查询</option><option value="review">审校当前正文</option><option value="rewrite">修改所选文字</option><option value="plan">讨论章节安排</option></select></label><p v-if="skill === 'rewrite'" class="muted">{{ selection?.text ? `已选择 ${selection.text.length} 个字符` : '请先在正文中选择要修改的文字。' }}</p><label>你的要求<textarea v-model="instruction" rows="3" placeholder="说说这一段想怎样写…"></textarea></label><button class="primary" :disabled="!chapter || !model || !selectedModel || selectedModel.price.policy.mode === 'unconfigured' || jobBusy || !!running || composing || (skill === 'rewrite' && !selection?.text)" @click="generate">{{ jobBusy ? '正在提交…' : '开始任务' }}</button><p v-if="jobError" class="error" role="alert">{{ jobError }} <button v-if="job" @click="poll(job.id)">重新读取任务</button></p><section v-if="job" class="job-card"><header><b>{{ job.status === 'succeeded' ? '候选已完成' : job.status === 'running' || job.status === 'queued' ? '正在创作…' : job.status === 'cancelled' ? '已停止' : '任务未完成' }}</b><button v-if="running" :disabled="jobBusy" @click="stop">停止</button></header><p class="muted">已扣 {{ points(job.billing.charged) }} 积分 · 预留 {{ points(job.billing.reserved) }} 积分</p><p v-if="job.billing.needsReconciliation" class="warning">上游用量待站长核对，相关积分仍在预留。</p><p v-if="job.task?.turn?.answer" class="assistant-answer">{{ job.task.turn.answer }}</p><p v-if="job.task?.error" class="error">{{ job.task.error.message }}</p><p v-if="job.error && !job.task?.error" class="error">任务未完成，现有内容已保留。请检查设定、章纲与积分状态。</p><template v-if="candidate"><pre class="candidate-text">{{ candidate.content }}</pre><details v-if="report"><summary>{{ report.passed ? '审校通过' : '审校需要复核' }}</summary><p>{{ report.summary }}</p><ul><li v-for="item in report.violations" :key="item">{{ item }}</li></ul></details><div v-if="candidate.diff" class="diff-list"><label v-for="block in candidate.diff.filter(b => b.kind === 'change')" :key="block.id" class="check-label"><input v-model="accepted" type="checkbox" :value="block.id"><span><del>{{ block.before }}</del><br><ins>{{ block.after }}</ins></span></label></div><label v-if="report && !report.passed" class="check-label"><input v-model="allowFailedReview" type="checkbox">我已核对审校问题，仍要采用</label><p v-if="dirty" class="warning">请先保存当前修改，再采用候选；正文已变化时需要重新核对。</p><button :disabled="adoptBusy || dirty || job.task?.chapterId !== chapter?.id || job.task?.artifact?.status === 'applied' || (!!report && !report.passed && !allowFailedReview)" @click="adopt">{{ job.task?.artifact?.status === 'applied' ? '已采用到正文' : '采用到当前正文' }}</button></template><pre v-else-if="job.task?.partial?.content && !job.task?.turn" class="candidate-text">{{ job.task.partial.content }}</pre></section><Annotations v-if="chapter" :key="chapter.id" :api="api" :owner="session.user.id" :chapter="chapter" :selection="selection" :locked="dirty || composing || busy || adoptBusy" @locate="(start, end) => editor?.select(start, end)" /><details v-if="jobs.length" class="job-history"><summary>本书任务记录（{{ jobs.length }}）</summary><button v-for="item in jobs" :key="item.id" @click="openJob(item.id)">{{ new Date(item.createdAt).toLocaleString('zh-CN') }} · {{ item.status }}</button></details></aside><div v-if="versions" class="modal-backdrop"><section class="paper-card dialog-card history-dialog" v-dialog="() => { versions = null; chosenVersion = null }" role="dialog" aria-modal="true" aria-label="正文历史"><header><h2>正文历史</h2><button @click="versions = null; chosenVersion = null">关闭</button></header><p v-if="!versions.length">尚无历史版本。</p><button v-for="version in versions" :key="version.id" @click="chosenVersion = version">{{ new Date(version.createdAt).toLocaleString('zh-CN') }} · {{ version.title }}</button><template v-if="chosenVersion"><pre class="candidate-text">{{ chosenVersion.content }}</pre><p>恢复会建立正式版本，原有历史保留。</p><button class="primary" :disabled="busy || dirty || composing" @click="restoreVersion">确认恢复此版本</button><p v-if="dirty" class="warning">请先保存当前正文。</p></template></section></div><ImportBook v-if="importOpen" :api="api" @close="importOpen = false" @imported="importOpen = false; refresh()" /></div></template>
